//! CHARTER: Vug (CODEX §2, 3D), a host face — the feature tree (VUGFACETREE, LEDGER SR513): the face's actions as
//! doc_core statements, undo / redo as Doc snapshots, the face regenerated by doc_core::replay; holds no geometry.
//!
//! "The feature tree must not break" (docs/dev/USERLAND/VUG.md §3 principle 3). The DOCUMENT is the face's truth:
//! every committed face action (a stroke's release, the arc's end click, an erase, a dimension's Enter, a committed
//! pull) calls [`Journal::record`], which re-writes the open sketch's statements from the face (THE face -> Doc writer:
//! [`cons`] / [`pref`] / [`sketch_doc`]) behind the frozen statements of the closed sketches and features, and appends
//! the extrude of a committed pull. A changed document pushes the old one on a snapshot stack bounded by
//! [`UNDO_DEPTH`]. When the history is edited — `u` / `U`, a statement deleted or a value changed in the panel — the
//! face and the body are regenerated by [`regenerate`] (doc_core's `replay`: the open sketch to a SketchFace, the solids
//! to the Body), so the tree never shows something the geometry is not; a replay failure names its line in the panel
//! and keeps the last good geometry and document. A deleted statement takes its dependants with it through doc_core's
//! own reader (`What::UnknownRef` by line) and replay (`Fault::Upstream` by line); `diff`'s Removed names them.
//!
//! Ids: sketch 0 is `s` with entities `e<n>` and constraints `k<n>`, sketch j > 0 is `s<j>` with `s<j>e<n>` /
//! `s<j>k<n>`, extrudes `x<n>`; a face slot keeps its name across regenerates (the slot maps in `Open`).

use crate::extrude::{Body, Pull};
use crate::raster::{self, Frame as Raster, rgba};
use crate::sketch::{ACTIVE, Design, Dim, Dimension, INK, REFUSED, SketchFace, type_into};
use crate::view::View;
use brep_core::Frame;
use doc_core::{Cons, Doc, Entry, Fault, PRef, PlainNames, SketchNames, Stmt, Tol, What};
use sketch_core::{ConstraintId, EntityId, Vec2};

/// The snapshots kept for undo (and for redo): one per committed action that changed the document, the oldest
/// dropped. Memory is this many documents (a document is its statements: a few hundred bytes a statement).
pub const UNDO_DEPTH: usize = 64;

/// The id of the first sketch (VUGFACEPHOTO's `photo::SKETCH_ID` names the same statement).
pub const FIRST_SKETCH: &str = "s";

/// A panel row's height, surface pixels.
pub const ROW_PX: f32 = 14.0;

/// The open sketch: its statement id, the prefix of its entity / constraint ids, the face slot -> doc id maps (every
/// slot, tombstones included) and the next free numbers.
#[derive(Clone, Debug, Default)]
struct Open {
    sketch: String,
    prefix: String,
    ents: Vec<String>,
    cons: Vec<String>,
    next_e: u32,
    next_k: u32,
}

impl Open {
    fn fresh(sketch: String) -> Open {
        let prefix = if sketch == FIRST_SKETCH { String::new() } else { sketch.clone() };
        Open { sketch, prefix, ..Default::default() }
    }

    /// Name every face slot not yet named (entities to the end of the entity list, constraints below `issued`).
    fn name_slots(&mut self, f: &SketchFace) {
        while self.ents.len() < f.sketch.entities().len() {
            self.ents.push(format!("{}e{}", self.prefix, self.next_e));
            self.next_e += 1;
        }
        while self.cons.len() < f.issued as usize {
            self.cons.push(format!("{}k{}", self.prefix, self.next_k));
            self.next_k += 1;
        }
    }

    fn ent(&self, e: EntityId) -> String {
        self.ents.get(e.0 as usize).cloned().unwrap_or_default()
    }
}

// VUGDOCFROMSKETCH (SR516): THE sketch_core -> text constraint map is doc_core's `sketch_cons` / `sketch_pref`; the
// names `journal::cons` / `journal::pref` stay for their callers.
pub use doc_core::{sketch_cons as cons, sketch_pref as pref};

// VUGDOCFROMSKETCH (SR516): the open sketch names its slots for doc_core's one writer (`from_sketch`).
impl SketchNames for Open {
    fn sketch(&self) -> String {
        self.sketch.clone()
    }
    fn entity(&self, slot: EntityId) -> String {
        self.ent(slot)
    }
    fn constraint(&self, id: ConstraintId) -> String {
        self.cons.get(id.0 as usize).cloned().unwrap_or_default()
    }
}

/// The face's sketch statements: the sketch on the face's plane, every live entity in face-id order, every live
/// constraint below `issued` in id order.
fn write_face(open: &Open, f: &SketchFace, out: &mut Vec<Stmt>) {
    // VUGDOCFROMSKETCH (SR516): doc_core's one writer, named by the open sketch's slot maps.
    let v3 = |p: brep_core::Vec3| [p.x, p.y, p.z];
    out.extend(doc_core::from_sketch(&f.sketch, (v3(f.plane.o), v3(f.plane.z), v3(f.plane.x)), f.issued, open));
}

/// A face's sketch alone as a document (sketch `s`, `e<n>` / `k<n>` by face id): the text a proposal names its
/// references in (VUGFACEPHOTO's `photo::doc_of` retires onto this at the fold).
pub fn sketch_doc(face: &SketchFace) -> Doc {
    // VUGDOCFROMSKETCH (SR516): `PlainNames` is exactly `Open::fresh("s")` + `name_slots` (`s` / `e<slot>` / `k<id>`).
    let v3 = |p: brep_core::Vec3| [p.x, p.y, p.z];
    let mut doc = Doc::new(Tol::DEFAULT);
    doc.stmts = doc_core::from_sketch(&face.sketch, (v3(face.plane.o), v3(face.plane.z), v3(face.plane.x)), face.issued, &PlainNames);
    doc
}

/// The first id `f(n)` no statement holds (one namespace).
fn free(stmts: &[Stmt], f: impl Fn(u32) -> String) -> String {
    (0u32..).map(f).find(|id| !stmts.iter().any(|s| s.id() == Some(id.as_str()))).unwrap_or_default()
}

fn sketch_id(j: u32) -> String {
    if j == 0 { FIRST_SKETCH.to_string() } else { format!("s{j}") }
}

/// The open sketch: the LAST sketch statement, when no extrude / revolve names it (its statements are the document's
/// tail: a sketch opens only after the previous one closed with its feature).
fn open_sketch(doc: &Doc) -> Option<usize> {
    let j = doc.stmts.iter().rposition(|s| matches!(s, Stmt::Sketch { .. }))?;
    let id = doc.stmts[j].id()?;
    let used = doc.stmts.iter().any(|s| matches!(s, Stmt::Extrude { sketch, .. } | Stmt::Revolve { sketch, .. } if sketch == id));
    if used { None } else { Some(j) }
}

/// What a regenerate gives: the face (the open sketch, if any) and the body (the solids, if any) for the design, and
/// the journal's open-sketch maps and frozen count.
pub struct Regen {
    pub face: Option<SketchFace>,
    pub body: Option<Body>,
    open: Option<Open>,
    closed: usize,
}

/// Regenerate the design from `doc` through doc_core's `replay`: a failure is `Err("line N: <fault> <id>")` and
/// nothing is built; else the solids become the Body and the open sketch a SketchFace (its plane by `Frame::new`, its
/// origin the point fixed at (0, 0), its dimensions re-placed beside their feet).
pub fn regenerate(doc: &Doc) -> Result<Regen, String> {
    let rep = doc_core::replay(doc, doc.tol);
    if let Some(f) = rep.failures.first() {
        return Err(format!("line {}: {:?} {}", f.line, f.fault, f.id));
    }
    let breps: Vec<brep_core::Brep> = rep.solids.iter().map(|s| s.brep.clone()).collect();
    let body = if breps.is_empty() { None } else { Some(Body::from_breps(breps, doc.tol)?) };
    let Some(j) = open_sketch(doc) else {
        return Ok(Regen { face: None, body, open: None, closed: doc.stmts.len() });
    };
    let Stmt::Sketch { id, o, z, x } = &doc.stmts[j] else { return Err(format!("line {}: not a sketch", doc.line(j))) };
    let v = |a: &[f64; 3]| brep_core::Vec3::new(a[0], a[1], a[2]);
    let plane = Frame::new(v(o), v(z), v(x)).map_err(|e| format!("line {}: {e:?} {id}", doc.line(j)))?;
    let sk = rep.sketches.iter().find(|s| s.id == *id).map(|s| s.sketch.clone()).ok_or_else(|| format!("line {}: Diverged {id}", doc.line(j)))?;
    let (mut ents, mut kons, mut origin) = (Vec::new(), Vec::new(), None);
    for s in &doc.stmts[j + 1..] {
        match s {
            Stmt::Point { id: e, sketch, .. } | Stmt::Line { id: e, sketch, .. } | Stmt::Circle { id: e, sketch, .. } | Stmt::Arc { id: e, sketch, .. }
                if sketch == id =>
            {
                ents.push(e.clone())
            }
            Stmt::Constraint { id: k, sketch, c } if sketch == id => {
                if let Cons::Fix(PRef::Point(p), at) = c {
                    if origin.is_none() && at[0] == 0.0 && at[1] == 0.0 {
                        origin = Some(p.clone());
                    }
                }
                kons.push(k.clone());
            }
            _ => {}
        }
    }
    let origin = origin.and_then(|p| ents.iter().position(|e| *e == p)).unwrap_or(0);
    let mut face = SketchFace::new(plane);
    face.sketch = sk;
    face.origin = EntityId(origin as u32);
    face.issued = kons.len() as u32;
    let dims: Vec<Dimension> = (0..face.issued)
        .filter_map(|i| {
            let dim = Dim::of(face.sketch.constraint(ConstraintId(i))?)?;
            let at = dim.foot(&face.sketch, Vec2::new(1e3, 1e3))?;
            Some(Dimension { constraint: ConstraintId(i), dim, anchor: Vec2::new(at.x + 3.0, at.y + 3.0) })
        })
        .collect();
    face.dims = dims;
    face.settle();
    let prefix = if id == FIRST_SKETCH { String::new() } else { id.clone() };
    let next = |names: &[String], tag: char| {
        names.iter().filter_map(|n| n.strip_prefix(prefix.as_str())?.strip_prefix(tag)?.parse::<u32>().ok()).max().map_or(0, |m| m + 1)
    };
    let (next_e, next_k) = (next(&ents, 'e'), next(&kons, 'k'));
    let open = Open { sketch: id.clone(), prefix: prefix.clone(), ents, cons: kons, next_e, next_k };
    Ok(Regen { face: Some(face), body, open: Some(open), closed: j })
}

/// The value a row edits, as shown: a dimension constraint's mm (an angle in degrees), an extrude's length, a
/// revolve's angle in degrees; None for a row without one.
pub fn value(s: &Stmt) -> Option<f64> {
    match s {
        Stmt::Constraint { c, .. } => match c {
            Cons::Distance(_, _, v) | Cons::DistancePointLine(_, _, v) | Cons::Radius(_, v) | Cons::Diameter(_, v) => Some(*v),
            Cons::Angle(_, _, t) => Some(t.abs().to_degrees()),
            _ => None,
        },
        Stmt::Extrude { length, .. } => Some(*length),
        Stmt::Revolve { angle, .. } => Some(angle.to_degrees()),
        _ => None,
    }
}

/// The statement with its value replaced by `v` (as [`value`] shows it; an angle keeps its sign).
fn with_value(s: &Stmt, v: f64) -> Option<Stmt> {
    let mut s = s.clone();
    match &mut s {
        Stmt::Constraint { c, .. } => match c {
            Cons::Distance(_, _, x) | Cons::DistancePointLine(_, _, x) | Cons::Radius(_, x) | Cons::Diameter(_, x) => *x = v,
            Cons::Angle(_, _, t) => {
                let sign = if *t < 0.0 { -1.0 } else { 1.0 };
                *t = v.to_radians() * sign;
            }
            _ => return None,
        },
        Stmt::Extrude { length, .. } => *length = v,
        Stmt::Revolve { angle, .. } => *angle = v.to_radians(),
        _ => return None,
    }
    Some(s)
}

/// The document, its snapshots and the panel.
#[derive(Clone, Debug)]
pub struct Journal {
    /// The face's truth.
    pub doc: Doc,
    /// Statements before this index are frozen (closed sketches and their features); the open sketch is the rest.
    closed: usize,
    open: Option<Open>,
    undo: Vec<Doc>,
    redo: Vec<Doc>,
    /// The panel is shown (`t`).
    pub panel: bool,
    /// The panel's cursor row (a statement index).
    pub cursor: usize,
    /// A row value being typed (Enter on a row with a value).
    pub edit: Option<String>,
    /// The last panel message: a refusal names its line (`line N: ...`), a delete names what went.
    pub note: Option<String>,
}

impl Default for Journal {
    fn default() -> Journal {
        Journal { doc: Doc::new(Tol::DEFAULT), closed: 0, open: None, undo: Vec::new(), redo: Vec::new(), panel: false, cursor: 0, edit: None, note: None }
    }
}

impl Journal {
    /// The snapshot counts (undo, redo).
    pub fn depth(&self) -> (usize, usize) {
        (self.undo.len(), self.redo.len())
    }

    /// The panel rows: the writer's lines (the header skipped), upper-cased (the raster font's case).
    pub fn rows(&self) -> Vec<String> {
        doc_core::write(&self.doc).lines().skip(1).map(str::to_uppercase).collect()
    }

    /// A committed face action: the open sketch re-written from `face` behind the frozen statements, and a committed
    /// `pull` appended as `extrude x<n>` (closing the sketch). A changed document is a snapshot.
    pub fn record(&mut self, face: Option<&SketchFace>, pull: Option<&Pull>) {
        let Some(f) = face else { return };
        let mut stmts: Vec<Stmt> = self.doc.stmts[..self.closed.min(self.doc.stmts.len())].to_vec();
        if self.open.is_none() {
            let id = free(&stmts, sketch_id);
            self.open = Some(Open::fresh(id));
        }
        let Some(open) = self.open.as_mut() else { return };
        open.name_slots(f);
        write_face(open, f, &mut stmts);
        let mut closing = false;
        if let Some(p) = pull {
            if let Some(src) = p.profile.outer.edges.first().map(|e| e.src()) {
                let z = [p.plane.z.x, p.plane.z.y, p.plane.z.z];
                let dir = if p.distance < 0.0 { z.map(|c| -c) } else { z };
                let id = free(&stmts, |n| format!("x{n}"));
                stmts.push(Stmt::Extrude { id, sketch: open.sketch.clone(), outer: open.ent(src), dir, length: p.distance.abs() });
                closing = true;
            }
        }
        if closing {
            self.closed = stmts.len();
            self.open = None;
        }
        self.commit(Doc { tol: self.doc.tol, stmts, lines: Vec::new() });
    }

    fn commit(&mut self, new: Doc) {
        if new == self.doc {
            return;
        }
        let old = std::mem::replace(&mut self.doc, new);
        self.undo.push(old);
        if self.undo.len() > UNDO_DEPTH {
            self.undo.remove(0);
        }
        self.redo.clear();
        self.cursor = self.doc.stmts.len().saturating_sub(1);
        self.note = None;
    }

    /// A history edit: regenerate `cand`, and only then make it the document (a snapshot).
    fn adopt(&mut self, cand: Doc) -> Result<Regen, String> {
        let mut r = regenerate(&cand)?;
        let cursor = self.cursor;
        self.commit(cand);
        self.open = r.open.take();
        self.closed = r.closed;
        self.cursor = cursor.min(self.doc.stmts.len().saturating_sub(1));
        Ok(r)
    }

    /// `u` (back) / `U`: the previous (next) snapshot regenerated; None with nothing to step to, or with the failure
    /// in the note (the snapshot stays where it was).
    pub fn step(&mut self, back: bool) -> Option<Regen> {
        let target = if back { self.undo.pop()? } else { self.redo.pop()? };
        match regenerate(&target) {
            Ok(mut r) => {
                let cur = std::mem::replace(&mut self.doc, target);
                if back {
                    self.redo.push(cur);
                } else {
                    self.undo.push(cur);
                }
                self.open = r.open.take();
                self.closed = r.closed;
                self.cursor = self.doc.stmts.len().saturating_sub(1);
                self.note = None;
                Some(r)
            }
            Err(e) => {
                if back {
                    self.undo.push(target);
                } else {
                    self.redo.push(target);
                }
                self.note = Some(e);
                None
            }
        }
    }

    /// Delete statement `i` and its dependants: doc_core's reader refuses a reference to a removed id
    /// (`UnknownRef`, by line) and replay names a statement that waited on one (`Upstream`, by line); each is removed
    /// until both are clean. Another refusal keeps everything and names its line. The origin point stays.
    pub fn delete(&mut self, i: usize) -> Result<Regen, String> {
        let row = self.doc.stmts.get(i).ok_or("no row")?;
        if let Stmt::Point { id, .. } = row {
            let fixed = self.doc.stmts.iter().any(|s| matches!(s, Stmt::Constraint { c: Cons::Fix(PRef::Point(p), at), .. } if p == id && at[0] == 0.0 && at[1] == 0.0));
            if fixed {
                return Err(format!("line {}: the origin stays", self.doc.line(i)));
            }
        }
        let mut cand = self.doc.clone();
        cand.lines.clear();
        cand.stmts.remove(i);
        for _ in 0..=self.doc.stmts.len() {
            match doc_core::read(&doc_core::write(&cand)) {
                Err(r) if matches!(r.what, What::UnknownRef(_)) && r.line >= 2 && ((r.line - 2) as usize) < cand.stmts.len() => {
                    cand.stmts.remove((r.line - 2) as usize);
                    continue;
                }
                Err(r) => return Err(format!("line {}: {:?}", r.line, r.what)),
                Ok(_) => {}
            }
            let rep = doc_core::replay(&cand, cand.tol);
            match rep.failures.iter().find(|f| matches!(f.fault, Fault::Upstream(_))) {
                Some(f) if f.line >= 2 && ((f.line - 2) as usize) < cand.stmts.len() => {
                    cand.stmts.remove((f.line - 2) as usize);
                }
                _ => break,
            }
        }
        let gone: Vec<String> = doc_core::diff(&self.doc, &cand)
            .entries
            .into_iter()
            .filter_map(|e| match e {
                Entry::Removed { id, .. } => Some(id),
                _ => None,
            })
            .collect();
        let r = self.adopt(cand)?;
        self.note = Some(format!("deleted {}", gone.join(" ")));
        Ok(r)
    }

    /// Enter on an open row edit: the typed value replaces the row's, through `regenerate` (a refusal names its line
    /// and nothing changes).
    fn commit_value(&mut self) -> Result<Regen, String> {
        let buf = self.edit.take().unwrap_or_default();
        let i = self.cursor;
        let v: f64 = buf.parse().map_err(|_| format!("line {}: Invalid", self.doc.line(i)))?;
        let s = self.doc.stmts.get(i).and_then(|s| with_value(s, v)).ok_or_else(|| format!("line {}: no value", self.doc.line(i)))?;
        let mut cand = self.doc.clone();
        cand.lines.clear();
        cand.stmts[i] = s;
        self.adopt(cand)
    }
}

/// The view's key, before the sketch face's: `u` / `U` undo / redo, `t` the panel; with the panel shown Up / Down,
/// Delete / BackSpace (the cursor row) and Enter (its value; then digits, Enter, Esc). None while a pull, a dimension
/// edit or a gesture is open, and for every other key.
pub fn key(d: &mut Design, k: &str) -> Option<bool> {
    if d.pull.is_some() || d.face.as_ref().is_some_and(|f| f.edit.is_some() || f.gesture.is_some()) {
        return None;
    }
    let enter = matches!(k, "Return" | "KP_Enter" | "\r" | "\n");
    let back = matches!(k, "BackSpace" | "Backspace" | "\u{8}" | "\u{7f}");
    let ch = {
        let mut it = k.chars();
        match (it.next(), it.next()) {
            (Some(c), None) => Some(c),
            _ => None,
        }
    };
    let j = &mut d.journal;
    let outcome: Result<Regen, String> = if let Some(buf) = j.edit.as_mut() {
        if enter {
            j.commit_value()
        } else if matches!(k, "Escape" | "\u{1b}") {
            j.edit = None;
            return Some(true);
        } else if type_into(buf, ch, back) {
            return Some(true);
        } else {
            j.edit = None;
            return None;
        }
    } else {
        match k {
            "u" | "U" => {
                let had = j.note.clone();
                match j.step(k == "u") {
                    Some(r) => Ok(r),
                    None => return Some(j.note != had),
                }
            }
            "t" => {
                j.panel = !j.panel;
                return Some(true);
            }
            _ if !j.panel => return None,
            "Up" | "\u{f700}" => {
                let c = j.cursor;
                j.cursor = c.saturating_sub(1);
                return Some(c != j.cursor);
            }
            "Down" | "\u{f701}" => {
                let c = j.cursor;
                j.cursor = (c + 1).min(j.doc.stmts.len().saturating_sub(1));
                return Some(c != j.cursor);
            }
            "Delete" | "\u{f728}" => j.delete(j.cursor),
            _ if back => j.delete(j.cursor),
            _ if enter => {
                match j.doc.stmts.get(j.cursor).and_then(value) {
                    Some(_) => {
                        j.edit = Some(String::new());
                        j.note = None;
                    }
                    None => j.note = Some(format!("line {}: no value", j.doc.line(j.cursor))),
                }
                return Some(true);
            }
            _ => return None,
        }
    };
    match outcome {
        Ok(r) => {
            d.face = r.face;
            d.body = r.body;
            d.pull = None;
            d.refusal = None;
        }
        Err(e) => d.journal.note = Some(e),
    }
    Some(true)
}

/// The panel: the right quarter of the frame, a row per statement (the cursor row tinted, an edit shown as
/// `<verb> <id> = <typed>`), the note at the bottom (a refusal in the refusal colour).
pub fn overlay(view: &View, fr: &mut Raster) {
    let j = &view.design.journal;
    if !j.panel {
        return;
    }
    let (w, h) = (fr.width as f32, fr.height as f32);
    let x0 = (w * 0.75).floor();
    raster::tint(fr, &[vec![(x0, 0.0), (w, 0.0), (w, h), (x0, h)]], rgba(raster::BACKGROUND), 0.9);
    raster::line(fr, (x0, 0.0), (x0, h), rgba(INK));
    let rows = j.rows();
    let fit = ((h - 2.0 * ROW_PX) / ROW_PX).floor().max(1.0) as usize;
    let first = j.cursor.saturating_sub(fit / 2).min(rows.len().saturating_sub(fit));
    let cols = ((w - x0 - 8.0) / 8.0).floor().max(1.0) as usize;
    let clip = |s: &str| s.chars().take(cols).collect::<String>();
    for (k, i) in (first..rows.len().min(first + fit)).enumerate() {
        let y = 4.0 + k as f32 * ROW_PX;
        let mut col = rgba(INK);
        let mut text = rows[i].clone();
        if i == j.cursor {
            raster::tint(fr, &[vec![(x0, y - 2.0), (w, y - 2.0), (w, y + ROW_PX - 2.0), (x0, y + ROW_PX - 2.0)]], rgba(ACTIVE), 0.25);
            if let Some(buf) = &j.edit {
                let head = text.split_whitespace().take(2).collect::<Vec<_>>().join(" ");
                text = format!("{head} = {buf}");
                col = rgba(ACTIVE);
            }
        }
        raster::text(fr, &clip(&text), x0 + 4.0, y, col);
    }
    if let Some(n) = &j.note {
        let col = if n.starts_with("line ") { rgba(REFUSED) } else { rgba(INK) };
        raster::text(fr, &clip(&n.to_uppercase()), x0 + 4.0, h - ROW_PX, col);
    }
}
